#!/usr/bin/env python3
"""
installer_maj_ressources_etapes_v1.py — Mise à jour « ressources par étape »
  1. Remplace data/plans_pays_v1.json par la version 1.1 (ressources par
     étape, canal associations, bouclier anti-arnaque, délais visa réels)
  2. Remplace app/api/moteur_plans.py par la version qui REND ces ressources
Les deux fichiers voyagent en base64 auto-vérifié (SHA-256 + ast/json),
avec .bak horodaté des versions actuelles. Idempotent.
Usage : python3 installer_maj_ressources_etapes_v1.py
"""
import ast, base64, hashlib, json, shutil, sys
from datetime import datetime
from pathlib import Path

RACINE = Path.home() / "mobilite-ia"

FICHIERS = {
    "data/plans_pays_v1.json": {
        "sha256": "f7422eb8905fa6ce7277632c3f27473fb646c343cc3bc21cea3d37dd203e51d5",
        "b64": "",
        "verif": "json",
    },
    "app/api/moteur_plans.py": {
        "sha256": "115579a16850e4a7d79e4ff6eb3b6cac28d28b35ce240ad8e9334fabb2ee8b74",
        "b64": "",
        "verif": "python",
    },
}

def main():
    for rel, info in FICHIERS.items():
        cible = RACINE / rel
        if not cible.exists():
            sys.exit(f"❌ {rel} absent — installer d'abord le moteur "
                     "(installer_moteur_plans_v1). Abandon.")
        data = base64.b64decode(info["b64"])
        if hashlib.sha256(data).hexdigest() != info["sha256"]:
            sys.exit(f"❌ Empreinte invalide : {rel} — abandon.")
        if info["verif"] == "python":
            ast.parse(data.decode("utf-8"))
            if "_maj_ressources_etapes_v1" not in data.decode("utf-8"):
                sys.exit("❌ Marqueur de version absent du module — abandon.")
        else:
            j = json.loads(data.decode("utf-8"))
            assert j["meta"]["version"] == "1.1"
            assert j["destinations"]["IT"].get("bouclier")
        if cible.read_bytes() == data:
            print(f"ℹ️  {rel} — déjà en version 1.1.")
            continue
        bak = cible.with_name(
            cible.name + f".bak-{datetime.now():%Y%m%d-%H%M%S}")
        shutil.copy2(cible, bak)
        cible.write_bytes(data)
        print(f"✅ {rel} → v1.1 (backup : {bak.name})")
    print()
    print("Terminé. Redémarrer (yorbity) puis régénérer un plan dans la")
    print("console : chaque étape affiche ses ressources 📚 et le plan")
    print("Italie inclut le Bouclier anti-arnaque 🛡️.")

if __name__ == "__main__":
    main()
